// serenityEvidenceValidationSchema validates a recorded Serenity evidence
// document against the adapter $defs: the root reference selects the named
// schema and the definitions resolve locally.
//
// adapterDefs is copied verbatim from the owned assignment and carries a
// top-level "adapter_mapping" catalog alongside "$defs" -- tooling metadata,
// not a schema keyword. Only "$defs" is spliced into the validation
// document; a naive whole-document splice would drag "adapter_mapping" into
// the merged schema's root and fail schema-syntax checking on it.
func serenityEvidenceValidationSchema() (json.RawMessage, error) {
	var doc map[string]json.RawMessage
	if err := json.Unmarshal([]byte(adapterDefs), &doc); err != nil {
		return nil, fmt.Errorf("serenity evidence schema: parse adapter defs: %w", err)
	}
	defs, ok := doc["$defs"]
	if !ok {
		return nil, fmt.Errorf("serenity evidence schema: adapter defs has no $defs")
	}
	merged := `{"$defs":` + string(defs) + `,"$ref":"#/$defs/SerenityEvidence"}`
	if err := checkSchemaDocument(merged); err != nil {
		return nil, fmt.Errorf("serenity evidence schema: %w", err)
	}
	return json.RawMessage(merged), nil
}

// mergeSchema splices one operation schema body into a copy of the shared
// $defs document. Every body starts with "{" and wireDefs ends with "}".
func mergeSchema(body string) (json.RawMessage, error) {
	merged := wireDefs[:len(wireDefs)-1] + "," + body[1:]
	return json.RawMessage(merged), nil
}

// checkSchemaDocument verifies that a merged schema document parses and that
// every document-local $ref resolves against its $defs. Registration fails
// closed on a broken schema instead of failing on the wire.
func checkSchemaDocument(doc string) error {
	var parsed map[string]json.RawMessage
	if err := contract.DecodeStrict([]byte(doc), &parsed); err != nil {
		return fmt.Errorf("schema document does not parse: %w", err)
	}
	rawDefs, ok := parsed["$defs"]
	if !ok {
		return fmt.Errorf("schema document has no $defs")
	}
	var defs map[string]json.RawMessage
	if err := contract.DecodeStrict(rawDefs, &defs); err != nil {
		return fmt.Errorf("schema $defs do not parse: %w", err)
	}
	var node any
	if err := contract.DecodeStrict([]byte(doc), &node); err != nil {
		return fmt.Errorf("schema document does not parse: %w", err)
	}
	return resolveRefs(node, defs)
}

// resolveRefs walks one decoded schema node checking every local $ref.
func resolveRefs(node any, defs map[string]json.RawMessage) error {
	switch v := node.(type) {
	case map[string]any:
		if ref, ok := v["$ref"].(string); ok {
			if !strings.HasPrefix(ref, "#/$defs/") {
				return fmt.Errorf("non-local $ref %q is not supported", ref)
			}
			name := strings.TrimPrefix(ref, "#/$defs/")
			if _, ok := defs[name]; !ok {
				return fmt.Errorf("$ref %q does not resolve", ref)
			}
			return nil
		}
		for _, child := range v {
			if err := resolveRefs(child, defs); err != nil {
				return err
			}
		}
	case []any:
		for _, child := range v {
			if err := resolveRefs(child, defs); err != nil {
				return err
			}
		}
	}
	return nil
}
